#include "exotic/autonomy/governance/evaluator.hpp"
#include <cassert>
#include <map>
using namespace exotic::autonomy;using namespace exotic::autonomy::governance;
namespace {class Repo final:public GovernanceRepository{public:ApprovalRequestId next_request_id()override{return 1;}DecisionId next_decision_id()override{return 1;}GrantId next_grant_id()override{return 1;}PolicyId next_policy_id()override{return 1;}EvidenceId next_evidence_id()override{return 1;}void save_request(const ApprovalRequest&)override{}std::optional<ApprovalRequest>load_request(ApprovalRequestId)override{return{};}std::vector<ApprovalRequest>load_pending(TimePoint)override{return{};}void append_decision(const ApprovalDecision&)override{}std::vector<ApprovalDecision>load_decisions(ApprovalRequestId)override{return{};}void save_grant(const CapabilityGrant&g)override{grants[g.subject_id].push_back(g);}std::vector<CapabilityGrant>load_grants(std::string_view s)override{return grants[std::string{s}];}void save_policy(const PolicyVersion&p)override{policies.push_back(p);}std::vector<PolicyVersion>load_active_policies()override{return policies;}void append_evidence(const DecisionEvidence&)override{}std::vector<DecisionEvidence>load_evidence(ApprovalRequestId)override{return{};}void set_emergency_stop(bool a,std::string_view,std::string_view)override{stop=a;}bool emergency_stop_active()override{return stop;}std::map<std::string,std::vector<CapabilityGrant>>grants;std::vector<PolicyVersion>policies;bool stop{};};}
int main(){Repo r;CapabilityGrant g;g.subject_id="agent";g.capability={"proposal.execute","proposal","proposal:7"};g.maximum_autonomy=AutonomyLevel::Bounded;g.budget_limit_usd=10;r.save_grant(g);PolicyVersion p;p.name="allow";p.rules.push_back({"allow",Effect::Allow,"proposal.execute","proposal","operator","","",RiskLevel::Minimal,false});r.save_policy(p);AuthorityEvaluator e{r};AuthorityContext c;c.subject={"agent",{"operator"},{}};c.resource={"proposal","8",{}};c.action="proposal.execute";c.requested_autonomy=AutonomyLevel::Bounded;c.budget_usd=1;assert(!e.evaluate(c).allowed);c.resource.id="7";assert(e.evaluate(c).allowed);}
